// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface CommitteeOut {
  committee_id: number;
  code: string;
  name: string;
  kind: "Quality" | "InfectionControl" | "PharmacyTherapeutics" | "MortalityMorbidity" | "MedicalRecords" | "Equipment" | "Credentials" | "WasteManagement" | "Safety" | "Other";
  terms_of_reference: string | null;
  meets_every_months: number;
  members: MemberOut[];
  is_active: boolean;
  row_version: number;
  /** The last meeting with final minutes */
  last_meeting_on: string | null;
  next_due_on: string | null;
  meetings: number;
  /** Its next meeting is due (or it never met) */
  is_due: boolean;
}

export interface MemberOut {
  user_id: number | null;
  name: string;
  role: "Chair" | "Secretary" | "Member";
  represents: string | null;
}

