/** A corrective or preventive action of the hospital's register (MSDS IMS 162, CQI 83, 107). */
export interface QualityActionOut {
  action_id: number;
  action_number: string;
  /** What found the need: a medical record review, an incident, a complaint, an infection control audit, a committee meeting, a mock drill, a mock PHC interview, a QA round, a patient's feedback */
  source: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback";
  cycle_id: number | null;
  cycle_number: string | null;
  incident_id: number | null;
  incident_number: string | null;
  complaint_id: number | null;
  complaint_number: string | null;
  ipc_audit_id: number | null;
  audit_number: string | null;
  meeting_id: number | null;
  meeting_number: string | null;
  drill_id: number | null;
  drill_number: string | null;
  mock_interview_id: number | null;
  /** The mock PHC interview that found the gap (MIV-...) */
  interview_number: string | null;
  qa_round_id: number | null;
  /** The in-charge's QA round whose finding it addresses (QAR-...) */
  qa_round_number: string | null;
  feedback_id: number | null;
  /** The patient feedback it answers (FB-...) */
  feedback_number: string | null;
  /** The number of the review cycle, the incident, the complaint, the audit or the meeting */
  source_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  /** A record review: the checklist item whose deficiencies it addresses */
  criterion_code: string | null;
  department_id: number | null;
  department_name: string | null;
  owner_user_id: number;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  outcome_note: string | null;
  completed_at: string | null;
  completed_by_name: string | null;
  created_by: number;
  created_by_name: string;
  created_at: string;
  row_version: number;
  is_overdue: boolean;
}

/** The committees — GET /api/v1/committees (who may call: any logged-in user: the committees they are a member of (all with committee.view or committee.manage)). */
export function listCommittees(query?: { active_only?: boolean }): Promise<CommitteeOut[]> {
  return api<CommitteeOut[]>("GET", withQuery(`/committees`, query), undefined);
}

/** A committee and its meetings — GET /api/v1/committees/{committee_id} (who may call: the committee's members, committee.view or committee.manage). */
export function getCommittee(committee_id: number): Promise<CommitteeDetailOut> {
  return api<CommitteeDetailOut>("GET", `/committees/${committee_id}`, undefined);
}

/** A meeting and its minutes — GET /api/v1/committee-meetings/{meeting_id} (who may call: the committee's members, committee.view or committee.manage). */
export function getMeeting(meeting_id: number): Promise<MeetingDetailOut> {
  return api<MeetingDetailOut>("GET", `/committee-meetings/${meeting_id}`, undefined);
}

/** Approve the minutes (final) — POST /api/v1/committee-meetings/{meeting_id}/finalize (who may call: the chair of the committee or committee.manage). */
export function finalizeMeeting(meeting_id: number): Promise<MeetingDetailOut> {
  return api<MeetingDetailOut>("POST", `/committee-meetings/${meeting_id}/finalize`, undefined);
}

/** The minutes (PDF) — GET /api/v1/committee-meetings/{meeting_id}/pdf (who may call: the committee's members, committee.view or committee.manage). */
export function minutesPdf(meeting_id: number): Promise<unknown> {
  return api<unknown>("GET", `/committee-meetings/${meeting_id}/pdf`, undefined);
}
